package main

import "sort"

// MergeIntervals merges all overlapping intervals in the input slice.
// Intervals are represented as [start, end] pairs.
func MergeIntervals(in [][]int) [][]int {
	if len(in) <= 1 {
		return in
	}

	// Sort intervals by start time
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	merged := make([][]int, 0, len(in))
	// Start with the first interval
	current := make([]int, 2)
	copy(current, in[0])

	for i := 1; i < len(in); i++ {
		if in[i][0] <= current[1] {
			// Overlapping: extend the end if needed
			if in[i][1] > current[1] {
				current[1] = in[i][1]
			}
		} else {
			// No overlap: append current and start a new one
			merged = append(merged, current)
			current = make([]int, 2)
			copy(current, in[i])
		}
	}
	// Append the last interval
	merged = append(merged, current)

	return merged
}
